function create_cookie(e,t,i){var o=new Date;o.setTime(o.getTime()+24*i*60*60*1e3);var n=o.toUTCString();document.cookie=e+"="+t+";expires="+n+";path=/;"}function retrieve_cookie(e){for(var t="",i="",o=e+"=",n=document.cookie.split(";"),r=n.length,c=0;c<r;c++)if(i=n[c].trim(),0==i.indexOf(o)){t=i.substring(o.length,i.length);break}return t}function delete_cookie(e){document.cookie=e+"=; expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/"}